'use strict';

const synthetics = require('Synthetics');
const log = require('SyntheticsLogger');

const HEALTH_PATHS = ['/health', '/health/live', '/health/ready'];

function endpointFor(baseUrl, path) {
  return new URL(path, `${baseUrl.replace(/\/$/, '')}/`);
}

async function verifyPath(baseUrl, site, path) {
  const target = endpointFor(baseUrl, path);
  const stepName = `${site}-${path.replace(/^\//, '').replace(/\//g, '-')}`;

  return synthetics.executeHttpStep(
    stepName,
    {
      hostname: target.hostname,
      method: 'GET',
      path: `${target.pathname}${target.search}`,
      port: 443,
      protocol: 'https:',
      headers: {
        'User-Agent': 'ai-resume-coach-ms023-synthetic/1.0',
        Accept: 'application/json',
      },
    },
    async (response) => {
      if (response.statusCode < 200 || response.statusCode >= 300) {
        throw new Error(`${path} returned HTTP ${response.statusCode}`);
      }
    },
  );
}

exports.handler = async () => {
  const baseUrl = process.env.API_ENDPOINT;
  const site = process.env.SITE || 'unknown';
  if (!baseUrl) {
    throw new Error('API_ENDPOINT is required');
  }

  log.info(`Validating ${site} public health contract at ${baseUrl}`);
  for (const path of HEALTH_PATHS) {
    await verifyPath(baseUrl, site, path);
  }
};
